+  --ok:#5ee0a3; --ok-tint:#123823;
+  --attention:#ffd166; --attention-tint:#3b3016;
+  --planned:#c5d0dc; --planned-tint:#1b2836;
+  --rail:272px; --toc:220px; --bar:56px;
+  color-scheme:dark;
+}
+:root[data-theme="light"]{
